"""Explain locked waits, time limits and queue insertion with concrete examples."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1485': ('공용 공책에 한 사람씩 쓰도록 열쇠를 정했다고 해 봅시다. 준비물을 기다리는 동안까지 열쇠를 쥐고 있으면, 준비물을 적어 줄 친구도 공책을 못 씁니다. 기다릴 때는 돌려주고, 다시 살펴볼 때 가져옵니다.', '잠금을 잡는 때와 풀고 기다리는 때를 순서대로 구별합니다.', '종이에 잠금 잡음 → 조건 확인 → 잠금 풀기 → 기다리기 → 다시 잡기 → 조건 확인을 그리세요. 마지막에도 잠금을 잡고 있다고 표시하세요.', ['잠금은 여러 작업이 같은 자료를 동시에 바꾸지 못하게 정한 규칙입니다. waitqueue는 기다리는 작업을 적어 두는 대기 줄입니다. 여기서 wq.lock은 그 대기 줄을 보호하는 잠금입니다. 열쇠 비유와 달리 실제 물건이 있는 것은 아닙니다.', 'wait_event_interruptible_locked를 부르기 전에는 호출자가 이미 wq.lock을 잡아야 합니다. 조건은 “준비된 물건이 있는가?” 같은 질문입니다. 이 질문을 확인할 때도 잠금을 잡고 있어야 다른 작업의 변경과 섞이지 않습니다.', '처음부터 조건이 맞으면 기다리는 부분을 건너뛰고 0을 돌려줍니다. 잠금도 그대로 잡고 있습니다. 0은 여기서 조건을 만족했다는 성공 표시입니다. 함수를 불렀다고 반드시 잠금이 한 번 풀리는 것은 아닙니다.', '기다려야 하면 do_wait_intr가 잠금을 풀고 schedule로 실행 기회를 다른 작업에 넘깁니다. 다시 실행되면 잠금을 잡습니다. 그 뒤 조건을 다시 확인합니다. 깨워졌다는 사실만으로 물건이 아직 남아 있다고 확신할 수 없어서 다시 묻는 것입니다.', 'interruptible은 신호로 기다림을 중단할 수 있다는 뜻입니다. 신호는 작업에게 보내는 알림입니다. do_wait_intr가 신호를 발견하면 잠금을 풀기 전에 -ERESTARTSYS라는 중단 코드를 돌려줍니다. 이 내부 반복문은 그 오류부터 보고 나가므로 모든 대기 코드가 조건을 먼저 본다고 외우면 안 됩니다.', '내부 대기를 마칠 때에는 대기 줄에서 내 항목을 빼고 TASK_RUNNING, 즉 실행 가능한 상태로 되돌립니다. 정상 종료든 신호 중단이든 잠금은 잡혀 있습니다. 호출자는 이후 필요한 일을 하고 알맞게 풀어야 합니다. 깨우는 쪽도 같은 잠금 규칙을 지켜 자료를 바꾼 뒤 wake_up_locked를 사용합니다.'], [('공책을 확인하려고 잠금을 잡고 locked 대기를 시작했어요. 이 호출이 끝나면 잠금은?', ['항상 풀려 있어요', '다시 잡았거나 계속 잡고 있어요'], '정답은 잠금을 잡은 상태입니다. 실제로 기다렸다면 풀었다가 다시 잡고, 처음부터 조건이 맞거나 신호 때문에 기다리지 않았다면 그대로 유지합니다. 기다리는 중에 풀린다는 말과 호출이 끝날 때 풀려 있다는 말은 달라요.'), ('“준비물이 도착했나?”라는 조건은 언제 확인하나요?', ['대기 줄의 잠금을 잡고 확인해요', '잠금을 풀고 잠든 동안에만 확인해요'], '조건 확인은 잠금을 잡은 구간에서 합니다. 잠든 동안에는 이 질문을 실행하지 않아요. 잠금을 풀고 기다리는 단계와 다시 잡고 확인하는 단계를 나누어 보세요.')]), 'os1486': ('대기 명단을 지키는 열쇠와 물건 창고를 지키는 열쇠는 다를 수 있습니다. 이번 코드에는 “이 열쇠를 잠깐 돌려주고 기다려 줘” 하고 넘기는 별도 잠금이 나옵니다.', '전달한 잠금, 추가 명령, 실제 기다림의 순서를 이해합니다.', '잠금 풀기 → cmd 실행 → schedule로 기다리기 → 잠금 다시 잡기를 적으세요. cmd 칸 아래에 잠금 없음이라고 쓰세요.', ['wait_event_lock_irq_cmd는 기다릴 조건과 lock이라는 잠금, cmd라는 추가 명령을 받습니다. cmd는 여기서 실행할 코드를 뜻합니다. wq_head는 대기 줄입니다. 이름이 따로 있는 이유는 맡은 일이 다르기 때문입니다.', '전달하는 lock은 조건에 쓰는 자료를 보호하는 잠금입니다. 대기 줄 자체를 보호하는 내부 잠금과 구별해야 합니다. 이 코드는 실제로 전달받은 lock을 풀고 다시 잡습니다. 인자를 무시하고 언제나 대기 줄 잠금만 쓰는 것이 아닙니다.', '실제 대기 부분의 순서는 spin_unlock_irq, cmd, schedule, spin_lock_irq입니다. 쉬운 말로는 잠금 풀기, 추가 명령 실행, 기다리기, 다시 잠금 잡기입니다. 그러므로 cmd는 이 전달 잠금의 보호를 받지 않는 구간에서 실행됩니다.', '왜 잠금을 풀까요? 조건을 참으로 바꿔 줄 다른 작업이 같은 잠금을 필요로 할 수 있기 때문입니다. 내가 잠금을 계속 쥐고 기다리면 그 작업도 자료를 바꾸지 못할 수 있습니다. 그렇다고 cmd에서 공유 자료를 마음대로 바꿔도 된다는 뜻은 아닙니다. 필요한 보호 규칙을 따로 지켜야 합니다.', 'irq는 인터럽트와 관련된 이름입니다. 인터럽트는 CPU가 처리할 알림이라고 생각하세요. 호출 전에는 이 잠금을 잡고 해당 CPU의 인터럽트를 꺼 둔 상태여야 합니다. spin_unlock_irq는 잠금을 풀며 인터럽트를 켜고, spin_lock_irq는 끄며 다시 잡습니다. 임의의 이전 상태를 저장했다 복구하는 irqsave 방식과 다릅니다.', '처음부터 조건이 맞으면 대기 부분과 cmd를 건너뜁니다. 여러 번 기다리면 cmd도 여러 번 실행될 수 있습니다. 끝나면 전달 잠금을 잡은 상태입니다. 대기 줄 준비 과정은 자체 잠금도 쓰므로 같은 잠금을 겹쳐 잡지 않도록 해야 합니다. 서로 다른 잠금은 어느 순서로 잡을지도 정해야 합니다.'], [('잠금을 풀기 → cmd → 기다리기 → 다시 잡기 순서예요. cmd를 실행할 때 전달 잠금은?', ['이미 다시 잡은 상태예요', '풀어 둔 상태예요'], 'cmd는 잠금을 푼 바로 다음에 있습니다. 다시 잡는 명령은 기다리기가 끝난 뒤에 있으므로 첫 번째 답은 순서를 거꾸로 읽은 것입니다. cmd가 보호받아야 하는 자료를 쓴다면 별도의 안전한 규칙이 필요해요.'), ('창고 자료를 보호하는 lock을 인자로 넘겼어요. 이 lock은 무조건 대기 명단의 잠금과 같나요?', ['아니요. 자료를 보호하는 별도 잠금을 전달하는 구조예요', '네. 전달한 인자는 버리고 명단 잠금만 써요'], '코드의 &lock은 전달받은 잠금을 가리킵니다. 대기 줄 내부 잠금은 준비 과정에서 따로 사용해요. 이름에 wait가 있다고 두 잠금을 같은 것으로 합쳐 생각하면 안 됩니다.')]), 'os1487': ('친구가 준비물을 가져올 때까지 기다리되, 시계의 눈금 다섯 칸만 기다린다고 해 봅시다. 기다리는 동안 공용 공책의 열쇠는 돌려주어야 친구가 도착 표시를 적을 수 있습니다.', '시간 제한 대기에서 잠금 순서와 성공·시간 만료·신호 중단을 구별합니다.', '결과표를 만드세요. 양수=조건 성공, 0=조건을 못 맞추고 시간 끝남, 음수 -ERESTARTSYS=신호 중단. 실제 기다림 앞뒤에 풀기와 다시 잡기를 적으세요.', ['lock_irq_timeout은 전달한 잠금과 기다릴 시간 제한을 함께 받습니다. 시간은 jiffies라는 커널 시간 눈금 단위입니다. 5를 주었다고 반드시 5초라는 뜻은 아닙니다. 눈금 한 칸의 길이는 커널 설정과 관련됩니다.', '실제로 기다리는 부분은 잠금 풀기 → schedule_timeout → 잠금 다시 잡기입니다. schedule_timeout은 남은 시간 안에서 기다리고 남은 눈금 수를 돌려줍니다. 다시 기다릴 때에는 그 남은 수를 사용하므로 매번 처음 시간으로 되돌려 무한히 연장하지 않습니다.', '조건을 만족하면 양수가 나옵니다. 조건이 거짓인 채 시간이 끝나면 0입니다. 남은 시간이 0인 경계에서 조건이 참이면 성공을 구별하려고 1을 씁니다. 그래서 결과 1을 “정확히 한 눈금이 남았다”로만 해석하면 안 됩니다.', 'interruptible이 붙은 변형에서는 허용된 신호로 중단될 때 -ERESTARTSYS라는 음수도 나올 수 있습니다. 결과가 0이 아닌지만 보면 성공인 양수와 중단인 음수를 섞게 됩니다. 양수인가, 0인가, 음수인가를 나누어 확인해야 합니다.', '처음부터 조건이 참이면 바깥 검사에서 끝날 수 있습니다. 이때는 내부 잠금 풀기 명령까지 가지 않습니다. 처음부터 시간 0이고 조건도 거짓이면 만료로 끝납니다. 이 시간 제한 도우미의 조건·만료 판정은 공통 반복문의 신호 오류 검사보다 앞에 있습니다.', '호출 전에는 전달 잠금을 잡고 해당 CPU 인터럽트를 꺼 둡니다. 실제로 기다릴 때에는 잠금을 풀고 인터럽트를 켰다가, 돌아와 끄고 잠금을 잡습니다. 성공, 만료, 신호 중단 어느 결과라도 호출이 끝날 때에는 잠금을 잡고 있다는 약속을 지킵니다. 시간 제한이 있다고 잠금을 잡은 채 잠들어도 되는 것은 아닙니다.'], [('시간 제한을 두고 실제로 기다리는 동안 전달 잠금을 계속 쥐고 있나요?', ['네. 시간이 끝날 때까지 놓지 않아요', '아니요. 풀고 기다렸다가 돌아오면 다시 잡아요'], '실제 순서는 spin_unlock_irq → schedule_timeout → spin_lock_irq입니다. 다른 작업도 자료를 바꿀 기회를 얻어야 하므로 기다리는 동안 풀어요. 시간이 제한되어 있다는 이유로 잠금을 계속 잡는 것은 아닙니다.'), ('처음부터 준비물이 있어서 조건이 참이에요. 잠금을 반드시 한 번 풀었다 잡나요?', ['아니요. 기다리는 부분을 건너뛰어 계속 잡고 있을 수 있어요', '네. 바로 끝나도 언제나 한 번 풀어요'], '바깥 조건 검사가 이미 성공이면 내부 대기를 부르지 않습니다. 잠금 풀기는 그 내부에 있으므로 실행되지 않아요. 결과적으로 끝날 때 잠금을 잡고 있다는 약속은 여전히 같습니다.')]), 'os1488': ('대기 줄 맨 앞에 우선권 표를 든 두 사람이 있고, 그 뒤에 일반 사람이 있다고 해 봅시다. 새 사람을 우선권 사람 뒤에 넣는 것과 줄 맨 끝에 넣는 것은 서로 다른 규칙입니다.', '대기 항목의 표시와 삽입 위치, 삭제 후 상태를 따로 읽습니다.', 'P1 → P2 → A를 두 번 그리세요. 앞쪽 도우미로 E를 넣으면 P1 → P2 → E → A, tail 도우미면 P1 → P2 → A → E가 되는지 확인하세요.', ['대기 줄의 항목에는 flags라는 표시 묶음이 있습니다. EXCLUSIVE는 깨우기 한도를 셀 때 쓰는 표시입니다. 이 표시가 있다고 줄에 나 혼자만 들어갈 수 있는 것은 아닙니다. 줄의 어느 자리에 넣는지도 표시 하나만으로 결정되지 않습니다.', '__add_wait_queue_exclusive는 EXCLUSIVE 표시를 붙이고 __add_wait_queue를 부릅니다. 밑줄 두 개까지 포함한 이 정확한 이름을 보세요. 이 도우미는 맨 앞에 연속으로 있는 PRIORITY, 즉 우선권 항목들을 지나 그 바로 뒤에 넣습니다.', '예를 들어 P1, P2가 우선권이고 A가 일반 항목이면 새 E는 P1 → P2 → E → A가 됩니다. 우선권 항목이 맨 앞에 없으면 새 항목을 줄 앞에 넣습니다. 따라서 “exclusive면 무조건 끝”이라고 외우면 틀립니다.', '__add_wait_queue_entry_tail_exclusive는 표시를 붙인 뒤 tail 도우미를 부릅니다. tail은 꼬리, 곧 맨 끝이라는 뜻입니다. 같은 예에서 P1 → P2 → A → E가 됩니다. 밑줄 두 개가 없는 외부 add_wait_queue_exclusive도 끝에 넣는 쪽이므로 비슷한 이름의 실제 호출을 확인해야 합니다.', '__remove_wait_queue는 list_del로 항목을 줄에서 뺍니다. 이것은 그 항목의 연결을 “나 자신을 가리키는 빈 줄”로 초기화하는 list_del_init과 다릅니다. 줄에서 뺐다고 항목 메모리까지 없애는 것도 아닙니다. 연결을 끊기, 빈 상태로 초기화하기, 메모리 돌려주기는 별개의 일입니다.', 'list_empty는 연결 상태를 보고 빈 줄인지 판단합니다. list_del만 한 항목을 초기화된 빈 줄이라고 가정해 다시 검사하면 안 됩니다. 다시 쓸 때에는 다음 함수가 요구하는 초기 상태를 만들어야 합니다. 이 내부 도우미들은 직접 잠금을 잡지 않으므로 호출자가 필요한 보호를 마련하고 사용해야 합니다.'], [('P1, P2는 맨 앞의 우선권 항목이고 A는 일반 항목이에요. 내부 __add_wait_queue_exclusive로 E를 넣으면?', ['exclusive니까 언제나 P1 → P2 → A → E예요', '앞쪽 삽입 규칙에 따라 P1 → P2 → E → A예요'], '이 함수는 __add_wait_queue를 부릅니다. 맨 앞 우선권 묶음 뒤에 넣으므로 E가 A보다 앞에 옵니다. 맨 끝에 넣는 tail 도우미나 비슷한 외부 함수와 구별하세요.'), ('__remove_wait_queue로 뺐어요. 연결이 자동으로 자기 자신을 가리키는 빈 줄 상태가 되나요?', ['아니요. list_del을 쓰므로 그런 초기화까지 하지 않아요', '네. 언제나 list_del_init처럼 초기화해요'], 'list_del은 줄에서 빼는 동작입니다. list_del_init은 뺀 뒤 초기화까지 하는 별도 동작이에요. 이 함수는 전자를 사용하므로 제거 후 바로 빈 줄이라고 가정하면 안 됩니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_367.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
